## 3. Full‑featured “missing‑icon” helper

If you need this logic in many places (multiple maps, many icons, caching, etc.) you can wrap it in a reusable function:

```js
/**
 * Registers a global missing‑image handler on a MapLibre map.
 *
 * @param {maplibregl.Map} map               The map instance.
 * @param {Object}        options            Configuration.
 * @param {string}        options.baseUrl   Base URL for icons (e.g. '/assets/icons/').
 * @param {function}      options.fallback  (id) => HTMLCanvasElement|ImageData|Image.
 *                                            Called when the fetch fails.
 * @param {boolean}       options.sdf       Whether to add images as SDF (default false).
 */
function enableMissingIconHandler(map, { baseUrl = '/', fallback = null, sdf = false } = {}) {
  // Keep a Set of ids we already tried – prevents an infinite loop if the fallback also fails.
  const tried = new Set();

  map.on('styleimagemissing', async (e) => {
    const { id } = e;
    if (tried.has(id)) {
      console.warn(`⚠️ Already tried to resolve "${id}" – giving up.`);
      return;
    }
    tried.add(id);

    const url = `${baseUrl.replace(/\/$/, '')}/${id}.png`;

    try {
      const img = await map.loadImage(url);
      map.addImage(id, img, { sdf });
      console.info(`✅ Loaded "${id}" from ${url}`);
    } catch (err) {
      console.error(`❌ Failed to load "${id}" from ${url}`, err);
      if (fallback) {
        try {
          const placeholder = fallback(id);
          map.addImage(id, placeholder, { sdf });
          console.info(`✅ Added fallback for "${id}"`);
        } catch (fallbackErr) {
          console.error(`❌ Fallback also failed for "${id}"`, fallbackErr);
        }
      }
    }
  });
}

/* -----------------------------------------------------------------
   Example usage
----------------------------------------------------------------- */
const map = new maplibregl.Map({ /* …same as before… */ });

enableMissingIconHandler(map, {
  baseUrl: 'https://my.cdn.com/icons',
  sdf: true, // if you use SDF icons (e.g., Mapbox’s “icon‑font” style)
  fallback: (id) => {
    // Very small red‑square placeholder – you could also return a pre‑loaded Image.
    const size = 24;
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ff5555';
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = '#fff';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('?', size / 2, size / 2);
    return canvas;
  }
});
```

### What the helper adds

| Feature | Why it matters |
|---------|----------------|
| **`tried` Set** | Guarantees we don’t get stuck in a loop if the fallback image is also missing. |
| **Custom `fallback`** | You can inject a pre‑loaded sprite, a canvas, or even a data‑URI. |
| **`sdf` flag** | If you use signed‑distance‑field icons (common for color‑tintable symbols), the flag must be set when adding the image. |
| **`baseUrl`** | Centralises the URL pattern; you can also pass a function instead of a string if you need per‑icon logic. |

