 *
 *   2. Run the script:
 *        node print-maplibre-version.js
 */

try {
  // 1️⃣ Load the library itself
  const maplibre = require('maplibre-gl');

  // 2️⃣ Prefer the public `version` property that the library exposes
  //    (this mirrors the same API that Mapbox GL JS provides)
