## 1️⃣  Minimal HTML page

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre – read camera state + projection matrix</title>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <!-- MapLibre GL CSS -->
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <style>
    body, html { margin:0; padding:0; height:100%; }
    #map { position:absolute; top:0; bottom:0; width:100%; }
    #info {
      position: absolute; bottom: 0; left: 0; right: 0;
      background: rgba(0,0,0,0.7); color:#fff; font-family:monospace;
      padding: .5rem; max-height: 30%; overflow:auto;
    }
    pre { margin:0; }
  </style>
</head>
<body>

<div id="map"></div>
<div id="info"><pre id="state"></pre></div>

<!-- MapLibre GL JS -->
<script src="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.js"></script>
<script>
  // --------------------------------------------------------------
  // 1️⃣  Initialise the map
  // --------------------------------------------------------------
  const map = new maplibregl.Map({
    container: 'map',
    style:    'https://demotiles.maplibre.org/style.json', // any public style works
    center:   [0, 0],   // lng, lat
    zoom:     2,
    pitch:    45,
    bearing:  20,
    // optional: try the globe projection
    // projection: 'globe'
  });

  // --------------------------------------------------------------
  // 2️⃣  Helper: format a Float32Array(16) as a nice 4×4 matrix string
  // --------------------------------------------------------------
  function formatMatrix(m) {
    // m is a Float32Array(16) in column‑major order (WebGL convention)
    const rows = [0, 1, 2, 3].map(r => {
      const cols = [0, 1, 2, 3].map(c => {
        // element (r,c) = m[c*4 + r] because of column‑major layout
        return m[c*4 + r].toFixed(4);
      }).join(', ');
      return `[ ${cols} ]`;
    });
    return rows.join('\n');
  }

  // --------------------------------------------------------------
  // 3️⃣  Read the camera state
  // --------------------------------------------------------------
  function readCameraState() {
    // 3a – high‑level getters (public API)
    const center   = map.getCenter();          // → maplibregl.LngLat
    const zoom     = map.getZoom();            // → number
    const bearing  = map.getBearing();         // → degrees
    const pitch    = map.getPitch();           // → degrees
    const projName = map.getProjection();      // e.g. "mercator" or "globe"

    // 3b – low‑level transform object (internal, but stable as of v4.x)
    //     The matrix is a Float32Array(16) in column‑major order.
    const projMatrix = map.transform._projMatrix; // <-- private API

    // 3c – optional: free‑camera options (another public way)
    // const freeOpts = map.getFreeCameraOptions();

    // Build a readable string
    const txt = [
      `center   : ${center.lng.toFixed(5)}, ${center.lat.toFixed(5)}`,
      `zoom     : ${zoom.toFixed(3)}`,
      `bearing  : ${bearing.toFixed(2)}°`,
      `pitch    : ${pitch.toFixed(2)}°`,
      `projection: ${projName}`,
      '',
      'Projection matrix (column‑major, 4×4):',
      formatMatrix(projMatrix)
    ].join('\n');

    document.getElementById('state').textContent = txt;
  }

  // --------------------------------------------------------------
  // 4️⃣  Keep the UI in sync – fire on every camera change
  // --------------------------------------------------------------
  // 'move' fires after any of center/zoom/bearing/pitch changes.
  // 'render' fires after the internal transform (and thus the matrix)
  // has been recomputed for the current frame.
  map.on('move', readCameraState);
  map.on('render', readCameraState);   // ensures matrix is fresh

  // Also run once as soon as the style is loaded
  map.once('load', readCameraState);
</script>
</body>
</html>
```

### What the script does

| Step | API used | What you get |
|------|----------|--------------|
| **Center** | `map.getCenter()` | `LngLat` object (`lng`, `lat`) |
| **Zoom**   | `map.getZoom()`   | floating‑point zoom level |
| **Bearing**| `map.getBearing()`| rotation in **degrees** (0 = north up) |
| **Pitch**  | `map.getPitch()`  | tilt in **degrees** (0 = flat) |
| **Projection name** | `map.getProjection()` | `"mercator"` (default) or `"globe"` (if you set `projection: 'globe'`) |
| **Projection matrix** | `map.transform._projMatrix` | `Float32Array(16)` – the exact matrix the WebGL shader receives. It is column‑major (the layout WebGL expects). |

> **⚠️  Private API warning**  
> `map.transform._projMatrix` is not part of the public documentation, but it has been stable across the 4.x series of MapLibre GL. If you need a future‑proof solution, you can also obtain the matrix from a **custom layer** (the `render` callback receives it as the `matrix` argument). The snippet below shows that alternative.

---

## 2️⃣  Getting the matrix from a custom layer (public API)

If you prefer to stay strictly within the public API, register a dummy custom layer that does nothing but expose the matrix each frame:

```js
const matrixLayer = {
  id: 'matrix‑debug',
  type: 'custom',
  renderingMode: '2d',          // or '3d' – doesn't matter for us
  onAdd: function (map, gl) {  // called once
    // no setup needed
  },
  render: function (gl, matrix) {
    // `matrix` is the same Float32Array(16) we saw earlier.
    // Store it somewhere you can read later:
    window._lastProjMatrix = matrix;
  }
};

map.addLayer(matrixLayer);

// Then you can read it whenever you like:
function readViaCustomLayer() {
  const m = window._lastProjMatrix;
  console.log('matrix from custom layer →', m);
}
```

The custom‑layer approach guarantees you are using only documented hooks, but it does add a tiny extra layer to the render pipeline (negligible for most apps).

---

## 3️⃣  Quick cheat‑sheet of the most useful getters

| Getter | Return type | Description |
|--------|-------------|-------------|
| `map.getCenter()` | `LngLat` | Geographic centre of the view |
| `map.getZoom()`   | `number` | Zoom level (0 = world, higher = more detail) |
| `map.getBearing()`| `number` | Rotation around the vertical axis, **degrees** |
| `map.getPitch()`  | `number` | Tilt of the camera, **degrees** |
| `map.getProjection()` | `string` | `"mercator"` (default) or `"globe"` |
| `map.getFreeCameraOptions()` | `{center, zoom, bearing, pitch, padding}` | All of the above in one object (useful for cloning or interpolation) |
| `map.transform._projMatrix` | `Float32Array(16)` | Internal 4 × 4 projection matrix (column‑major) |
| `map.project(lngLat)` | `Point` | Convert a geographic coordinate → screen pixel |
| `map.unproject(point)` | `LngLat` | Convert a screen pixel → geographic coordinate |

---

## 4️⃣  Using the matrix for your own math

The matrix you receive is the **combined view‑projection matrix** that transforms a point from *world* (Mercator or globe) coordinates into *clip space* (the `[-1, 1]` cube that WebGL finally rasterises).  

If you want to transform a point yourself:

```js
// Example: world → clip → NDC → screen
function worldToScreen(lng, lat, altitude = 0) {
  // 1️⃣  Convert lng/lat to the map's internal Mercator (or globe) XYZ
  const world = mapboxgl.MercatorCoordinate.fromLngLat(
    {lng, lat},
    altitude   // meters above the ground
  );

  // 2️⃣  Put XYZ into a homogeneous vec4 (w = 1)
  const vec = [world.x, world.y, world.z, 1];

  // 3️⃣  Multiply by the projection matrix (column‑major)
  const m = map.transform._projMatrix;
  const clip = [
    m[0]*vec[0] + m[4]*vec[1] + m[8]*vec[2] + m[12]*vec[3],
    m[1]*vec[0] + m[5]*vec[1] + m[9]*vec[2] + m[13]*vec[3],
    m[2]*vec[0] + m[6]*vec[1] + m[10]*vec[2] + m[14]*vec[3],
    m[3]*vec[0] + m[7]*vec[1] + m[11]*vec[2] + m[15]*vec[3]
  ];

  // 4️⃣  Perspective divide → Normalised Device Coordinates
  const ndc = clip.map(v => v / clip[3]);

  // 5️⃣  Convert NDC to pixel coordinates
  const canvas = map.getCanvas();
  const x = (ndc[0] + 1) / 2 * canvas.width;
  const y = (1 - ndc[1]) / 2 * canvas.height; // note Y flip

  return {x, y};
}
```

That snippet shows the *raw* way to use the matrix. In most cases you can rely on the built‑in helpers `map.project()` / `map.unproject()`, but having the matrix gives you full control for custom shaders, hit‑testing, or any non‑standard projection math you might need.

