  const map = new maplibregl.Map({
    container: 'map',
    style:    'https://demotiles.maplibre.org/style.json',
    center:   [0, 0],
    zoom:     2,
    pitch:    45,
    bearing:  30,
    antialias: true               // needed for 3‑d custom layers
  });

  // --------------------------------------------------------------
  // 2️⃣  Helper that extracts *all* the data we care about
  // --------------------------------------------------------------
  function readCameraState() {
    // ---- Public, documented API -------------------------------------------------
    const center  = map.getCenter();          // → maplibregl.LngLat
    const zoom    = map.getZoom();            // → number
    const bearing = map.getBearing();         // → number (degrees, clockwise)
    const pitch   = map.getPitch();           // → number (degrees)

    // ---- Free‑camera options (same data, but in a single object) ---------------
    //   This is handy if you ever want to feed the object straight back into
    //   map.setFreeCameraOptions().
    const freeCam = map.getFreeCameraOptions(); // {center, zoom, bearing, pitch, padding…}

    // ---- Projection matrix (private, but stable as of v4.x) --------------------
    //   The matrix is a Float32Array[16] in column‑major order (the same layout
    //   WebGL expects).  It already contains the view‑transform (camera position)
    //   *and* the projection (perspective/orthographic) part.
    const projMatrix = map.transform._projMatrix; // ← private API

    // If you prefer a plain JS array you can do:
    // const projMatrixArray = Array.from(projMatrix);

    // ---- Return everything in a tidy object ------------------------------------
    return {
      center:   { lng: center.lng, lat: center.lat },
      zoom,
      bearing,
      pitch,
      freeCameraOptions: freeCam,
      // expose the raw Float32Array – you can pass it directly to WebGL shaders
      projectionMatrix: projMatrix
    };
  }

  // --------------------------------------------------------------
  // 3️⃣  Show the state whenever the camera moves (drag, zoom, rotate, …)
  // --------------------------------------------------------------
  function updateInfo() {
    const state = readCameraState();
    const infoDiv = document.getElementById('info');

    // Pretty‑print the matrix (4 rows × 4 columns)
    const mat = state.projectionMatrix;
    const matRows = [
      `${mat[0].toFixed(4)} ${mat[4].toFixed(4)} ${mat[8].toFixed(4)} ${mat[12].toFixed(4)}`,
      `${mat[1].toFixed(4)} ${mat[5].toFixed(4)} ${mat[9].toFixed(4)} ${mat[13].toFixed(4)}`,
      `${mat[2].toFixed(4)} ${mat[6].toFixed(4)} ${mat[10].toFixed(4)} ${mat[14].toFixed(4)}`,
      `${mat[3].toFixed(4)} ${mat[7].toFixed(4)} ${mat[11].toFixed(4)} ${mat[15].toFixed(4)}`
    ].join('\n');

    infoDiv.textContent = `
center   : ${state.center.lng.toFixed(5)}, ${state.center.lat.toFixed(5)}
zoom     : ${state.zoom.toFixed(3)}
bearing  : ${state.bearing.toFixed(2)}°
pitch    : ${state.pitch.toFixed(2)}°
matrix   :\n${matRows}
`.trim();
  }

  // Listen to any event that changes the camera.  'move' fires continuously while
  // the user is dragging/zooming; 'render' fires once per frame (including after
  // programmatic changes).  Pick whichever granularity you need.
  map.on('move', updateInfo);
  map.on('render', updateInfo);   // ensures we get the initial state as soon as the map draws

  // --------------------------------------------------------------
  // 4️⃣  OPTIONAL: use the matrix inside a custom WebGL layer
  // --------------------------------------------------------------
  // The matrix argument that MapLibre passes to a custom layer's `render`
  // callback is *exactly* the same Float32Array you read above.
  // Below is a minimal custom layer that just logs the matrix once.
  const logLayer = {
    id: 'log-matrix',
    type: 'custom',
    renderingMode: '3d',
    onAdd: function (map, gl) {
      console.log('Custom layer added – matrix will be logged on first render');
    },
    render: function (gl, matrix) {
      console.log('Matrix from custom layer render():', matrix);
      // You could now upload `matrix` to a shader uniform, etc.
    }
  };
  map.on('load', () => map.addLayer(logLayer));
</script>
</body>
</html>
```

---

## What the code does, step‑by‑step

| Step | API used | What you get |
|------|----------|--------------|
| **Center** | `map.getCenter()` | `LngLat` object (`lng`, `lat`) |
| **Zoom**   | `map.getZoom()`   | Number (0 = world view) |
| **Bearing**| `map.getBearing()`| Number in degrees, clockwise from north |
| **Pitch**  | `map.getPitch()`  | Number in degrees (0 = flat) |
| **Free‑camera options** | `map.getFreeCameraOptions()` | `{center, zoom, bearing, pitch, padding, ...}` – handy if you later want to call `map.setFreeCameraOptions()` |
| **Projection matrix** | `map.transform._projMatrix` (private) | `Float32Array(16)` – column‑major 4×4 matrix ready for WebGL |

> **⚠️ Private API warning**  
> `map.transform._projMatrix` is not part of the public documentation, but it has been stable across the 4.x series of MapLibre GL JS. If you need a *future‑proof* solution, the matrix is also supplied automatically to any **custom layer** via the `render(gl, matrix)` callback (see the `logLayer` example). That is the officially supported way to get the exact matrix the renderer is using.

---

## Quick‑reference cheat‑sheet

```js
// ----- Public getters -------------------------------------------------
const center  = map.getCenter();   // → {lng, lat}
const zoom    = map.getZoom();     // → number
const bearing = map.getBearing();  // → degrees
const pitch   = map.getPitch();    // → degrees

// ----- One‑object version -------------------------------------------------
const cam = map.getFreeCameraOptions(); // {center, zoom, bearing, pitch, padding…}

// ----- Projection matrix (internal) --------------------------------------
const projMatrix = map.transform._projMatrix; // Float32Array[16]

// ----- If you only need the view‑projection matrix inside a custom layer -----
map.addLayer({
  id: 'my-layer',
  type: 'custom',
  renderingMode: '3d',
  onAdd: (map, gl) => { /* init GL resources */ },
  render: (gl, matrix) => {
    // `matrix` === map.transform._projMatrix
    // → upload to shader, do math, etc.
  }
});
```

---

### Why you might need the matrix

* **Custom WebGL shaders** – pass the matrix as a uniform (`u_matrix`) and transform your own vertex data exactly like MapLibre does.
* **Ray‑casting / picking** – invert the matrix to go from screen space back to world coordinates.
* **Geodesic calculations** – combine the matrix with your own math (e.g., projecting a 3‑D model onto the globe).

---

### TL;DR

* Use the **public getters** (`getCenter`, `getZoom`, `getBearing`, `getPitch`) for the simple scalar values.
* Use **`map.getFreeCameraOptions()`** if you want them all in one object.
* Grab the **projection matrix** from `map.transform._projMatrix` (or from the `render` callback of a custom layer) and you have the exact 4 × 4 matrix that MapLibre GL JS uses for rendering.

Happy coding! 🚀
